-- public.creature_refusal(p_world uuid, p_uid uuid, p_action text, p_target jsonb)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.creature_refusal(p_world uuid, p_uid uuid, p_action text, p_target jsonb)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
declare c creature; d species_def; food text; held int; working int; cap int; q creature; pl player;
begin
  -- Opening a crate you carry is asked of the crate, not of a creature.
  if p_action in ('crate_follow', 'crate_work') then
    return crate_open_refusal(p_world, p_uid, p_action, p_target);
  end if;
  -- Work around me, and its Stop (`around_refusal`).
  if p_action in ('work_around', 'stop_work_around') then
    return around_refusal(p_world, p_uid, p_action, p_target);
  end if;
  -- Walked forward before it is looked at: where it was is not where it is.
  perform creature_settle(p_world, (p_target->>'id')::int);
  c := target_creature(p_world, p_target);
  if c.world_id is null then return 'Gone.'; end if;
  select * into d from species_def where id = c.species;

  -- In the traces until somebody takes it out: nothing that would send it
  -- anywhere else is open to it, in the words culling one already uses.
  if p_action in ('assign_deed', 'take_creature', 'crate_creature', 'release_creature')
     and c.hitched_to is not null then
    return c.name || ' is in the traces: unhitch it first.';
  end if;

  -- Only your own is yours to send anywhere, put in a crate, order about or name.
  if p_action in ('take_creature', 'assign_deed', 'crate_creature', 'release_creature', 'cull_creature',
                  'set_stance', 'order_attack', 'order_heel', 'rename_creature')
     and c.mode <> 'wild' and c.keeper is distinct from p_uid then
    return c.name || ': not yours.';
  end if;

  -- An order is heard from wherever you stand, as a stance is.
  if p_action not in ('examine_creature', 'assign_deed', 'set_stance', 'order_attack', 'order_heel')
     and not creature_in_reach(p_world, p_uid, c) then
    return case when c.mode = 'wild' then d.name || ': too far.'
                else 'Stand next to ' || c.name || '.' end;
  end if;

  -- An ancient comb, file or pot (`artifact_refusal`).
  if artifact_action(p_action) then return artifact_refusal(p_world, p_uid, p_action, c); end if;
  -- Wildermon gear (`gear_refusal`).
  if gear_action(p_action) then return gear_refusal(p_world, p_uid, p_action, c, p_target); end if;

  if p_action = 'tame' then
    if d.monster then
      return d.name || ': cannot be tamed.';
    end if;
    if c.mode <> 'wild' then return c.name || ' is already yours.'; end if;
    if skill_of(p_world, p_uid, 'taming') < (tame_needs(c)).level then
      return 'Need taming ' || to_char((tame_needs(c)).level, 'FM990.#') || '.';
    end if;
    if bait_in_pack(p_world, p_uid, c.species, pk(p_world, p_uid, 'bait:any', 0) > 0) is null then
      return 'Need an offering: ' || diet_text(c.species) || '.';
    end if;
    -- The first follows you, and every one after that goes into a crate you carry.
    return tame_room_refusal(p_world, p_uid);

  elsif p_action = 'assign_deed' then
    if c.mode = 'wild' then return 'Not yours.'; end if;
    if c.mode = 'stored' then return c.name || ' is in a wildermon crate: open it first.'; end if;
    if (my_deed(p_world, p_uid)).world_id is null then
      return 'No settlement.';
    end if;
    if d.gathers is null and d.style is distinct from 'spar' then return d.name || ': no task.'; end if;
    -- A trade asked for by name has to be one of its own.
    if nullif(p_target->>'job', '') is not null
       and not (p_target->>'job' = d.gathers or p_target->>'job' = any(coalesce(d.trades, '{}'::text[]))) then
      return d.name || ': not one of its tasks.';
    end if;
    if d.gathers is not null and not worker_job_ported(coalesce(nullif(p_target->>'job', ''), d.gathers)) then
      return 'Not on islands yet: '
        || (select verb from gather_def where id = coalesce(nullif(p_target->>'job', ''), d.gathers))
        || '.';
    end if;
    -- One off a post takes a place as much as one off the road, since a post costs none.
    if c.mode <> 'deed' or c.post is not null or c.around is not null then
      working := workers_on_deed(p_world, p_uid);
      cap := worker_cap(p_world, p_uid);
      if working >= cap then
        return (my_deed(p_world, p_uid)).name || ' full: ' || cap
          || ' workers at level ' || cap || '.';
      end if;
    end if;
    return null;

  elsif p_action = 'feed' then
    if c.mode not in ('active', 'deed') then return 'Not yours.'; end if;
    -- Its own diet, or a bucket of whey, which every kind takes (`feed_in_pack`).
    if (feed_in_pack(p_world, p_uid, c.species, p_target)).id is null then
      return 'Eats: ' || diet_text(c.species) || ', or a bucket of whey.';
    end if;
    return null;

  elsif p_action = 'groom' then
    if d.monster then return d.name || ': cannot be brushed.'; end if;
    if c.mode = 'wild' then return 'Not yours.'; end if;
    if pack_count(p_world, p_uid, 'brush') <= 0 then return 'Need a brush.'; end if;
    if c.care >= 0.995 then return c.name || ': care full.'; end if;
    return null;

  elsif p_action = 'shear' then
    if d.fleece is null then return 'Nothing to shear.'; end if;
    if c.mode = 'wild' then return 'Tame it first.'; end if;
    if pack_count(p_world, p_uid, 'carving_knife') <= 0 then return 'Need a carving knife.'; end if;
    if c.fleece < 0.35 then
      return c.name || ': '
        || case when d.shear_yield = 'feather' then 'feathers' else 'fleece' end || ' under 35% grown.';
    end if;
    return null;

  elsif p_action = 'milk_creature' then
    if not d.milk then return 'Cannot be milked.'; end if;
    if c.mode in ('wild', 'stored') then return 'Not yours.'; end if;
    -- Less than a bucket a milking goes on into a part bucket of milk, if there is one (`milk_go`).
    if pack_count(p_world, p_uid, 'bucket') <= 0
       and not (milk_litres(c.species) < bucket_litres() and pack_count(p_world, p_uid, 'milk_part') > 0) then
      return 'Need an empty bucket.';
    end if;
    if c.sex <> 'female' then return c.name || ' is male.'; end if;
    if c.fleece < milk_ready() then return c.name || ': no milk yet.'; end if;
    return null;

  elsif p_action = 'set_stance' then
    if c.mode <> 'active' then return 'Companions only.'; end if;
    if coalesce(p_target->>'stance', '') not in ('passive', 'defensive', 'aggressive', 'guard') then
      return 'Stance: passive, defensive, guarding you or aggressive.';
    end if;
    return null;

  elsif p_action = 'order_attack' then
    if c.mode <> 'active' then return 'Companions only.'; end if;
    if coalesce(p_target->>'foe', '') !~ '^[0-9]+$' then return 'No target: mark a wild one or fight it.'; end if;
    select * into q from creature where world_id = p_world and id = (p_target->>'foe')::int;
    if not found or q.mode <> 'wild' or q.hitched_to is not null then return 'No target: mark a wild one or fight it.'; end if;
    select * into pl from player where world_id = p_world and uid = p_uid;
    -- As far as it follows a fight: further for a Beastmaster's Long Leash.
    if sqrt((creature_x(q) - pl.x) ^ 2 + (creature_y(q) - pl.y) ^ 2) > pk(pl.class_mul, 'leash:companion', companion_leash()) then
      return 'Too far: max ' || pk(pl.class_mul, 'leash:companion', companion_leash()) || ' tiles.';
    end if;
    return null;

  elsif p_action = 'order_heel' then
    if c.mode <> 'active' then return 'Companions only.'; end if;
    return null;

  elsif p_action = 'rename_creature' then
    if c.mode = 'wild' then return 'Not yours.'; end if;
    if nullif(btrim(coalesce(p_target->>'name', '')), '') is null then return 'Need a name.'; end if;
    return null;

  elsif p_action = 'take_creature' then
    if c.mode = 'stored' then return c.name || ' is in a wildermon crate: open it first.'; end if;
    if c.mode <> 'deed' then return 'Already with you.'; end if;
    -- Where the one following you now goes, or why it has nowhere to.
    return (companion_swap(p_world, p_uid, c)).v_why;

  elsif p_action = 'crate_creature' then
    if c.mode = 'stored' then return c.name || ' is already in a wildermon crate.'; end if;
    if c.mode not in ('active', 'deed') then return 'Not yours.'; end if;
    if c.rider is not null then return 'Get down off ' || c.name || ' first.'; end if;
    if empty_crate(p_world, p_uid) is null then return 'Need an empty wildermon crate in your pack.'; end if;
    return pannier_exit_refusal(p_world, c);

  elsif p_action = 'release_creature' then
    if c.mode = 'wild' then return 'Already wild.'; end if;
    if pannier_exit_refusal(p_world, c) is not null then return pannier_exit_refusal(p_world, c); end if;
    if c.mode = 'stored' and exists (select 1 from item i where i.world_id = p_world and i.creature = c.id
                                        and (i.deal is not null or i.holder <> 'player')) then
      return c.name || '''s crate is on offer, on a stall or in the post: take it back first.';
    end if;
    return null;

  elsif p_action = 'cull_creature' then
    -- Only your own, and only one that is not in the traces or under you when
    -- you ask: both of those are a mess this does not have to make.
    if c.mode = 'wild' then return 'Not yours.'; end if;
    if c.hitched_to is not null then return c.name || ' is in the traces: unhitch it first.'; end if;
    if c.rider is not null then return 'Get down off ' || c.name || ' first.'; end if;
    if pannier_exit_refusal(p_world, c) is not null then return pannier_exit_refusal(p_world, c); end if;
    if c.mode = 'stored' and exists (select 1 from item i where i.world_id = p_world and i.creature = c.id
                                        and (i.deal is not null or i.holder <> 'player')) then
      return c.name || '''s crate is on offer, on a stall or in the post: take it back first.';
    end if;
    return null;
  end if;
  return null;
end $function$
